                        + " (lease_id, seq, segment_id, asset_id, grant_id, grant_revoked,"
                        + "  start_ms, end_ms, acked)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0)",
                leaseId, seq, segmentId, assetId, grantId, grantRevoked, startMs, endMs);
    }

